def quote(text):
    # MySQL consumes backslash escapes before JSON parsing; double them for SQL.
    return "'" + str(text).replace('\\','\\\\').replace("'","''") + "'"
def metadata(value): return quote(json.dumps(value,ensure_ascii=False))
def set_id(part,level):
    return f"(SELECT id FROM practice_sets WHERE skill='READING' AND part_no={part} AND instructions LIKE '[READING_PART{part}_LEVEL:{level}]%' ORDER BY id LIMIT 1)"
def add_question(sql,sid,pid,order,text,meta,options,answer):
    assert len(options)==len(set(options))==4 and answer in 'ABCD'
    where=f'practice_set_id={sid} AND question_text={quote(text)}'+(f' AND passage_id={pid}' if pid else ' AND passage_id IS NULL')
    sql.append(f'INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT {sid},{pid or "NULL"},{quote(text)},{metadata(meta)},{order} WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE {where});')
    qid=f'(SELECT id FROM practice_questions WHERE {where} ORDER BY id LIMIT 1)'
    for label,option in zip('ABCD',options):
        sql.append(f'INSERT INTO practice_options(question_id,option_label,option_text,is_correct) SELECT {qid},{quote(label)},{quote(option)},{str(label==answer).upper()} WHERE NOT EXISTS(SELECT 1 FROM practice_options WHERE question_id={qid} AND option_label={quote(label)});')
def main():
    sql=['-- N11 original Reading expansion: +10 Part 5, +20 Part 6, +17 Part 7 questions.', '-- Import after 003-005. Additive and rerunnable; existing attempts keep their question snapshot.', 'SET AUTOCOMMIT=0;']
    for index,(level,text,vi,options,meanings,key,reason,words) in enumerate(P5):
        add_question(sql,set_id(5,level),None,7+index%2,text,dict(translation=vi,options_vi=dict(zip('ABCD',meanings)),explanation=reason,words=words),options,key)
    for part,packs in [(6,P6),(7,P7)]:
        for level,(title,content,questions,glossary) in enumerate(packs,1):
            sid=set_id(part,level)
            payload=dict(title=title,glossary=glossary)
            payload.update(dict(lines=[dict(en=en,vi=vi) for en,vi in content]) if part==6 else dict(documents=content))
            # Stable batch identifier avoids changing or reusing existing passages.
            payload['content_key']=f'n11-reading-expansion-20261116-p{part}-l{level}'
            match=f'practice_set_id={sid} AND passage_text LIKE {quote("%"+payload["content_key"]+"%")}'
            sql.append(f'INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT {sid},{metadata(payload)},2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE {match});')
            pid=f'(SELECT id FROM practice_passages WHERE {match} ORDER BY id LIMIT 1)'
            for i,item in enumerate(questions):
                if part==6:
                    options,meanings,key,reason=item
                    text=f'Chọn đáp án cho chỗ trống [{135+i}]'
                    meta=dict(options_vi=dict(zip('ABCD',meanings)),explanation=reason)
                else:
                    text=item['text'];options=item['options'];key=item['correct']
                    meta={k:v for k,v in item.items() if k not in ['text','options','correct']}
                add_question(sql,sid,pid,135+i if part==6 else 160+i,text,meta,options,key)
    output='\n'.join(sql+['COMMIT;','SET AUTOCOMMIT=1;',''])
    (ROOT/'database/updates/006_reading_expansion.sql').write_text(output,encoding='utf-8')
    path=ROOT/'database/n11_toeic.sql';marker='-- BEGIN N11 READING EXPANSION'
    path.write_text(path.read_text(encoding='utf-8').split(marker)[0].rstrip()+'\n\n'+marker+'\n'+output,encoding='utf-8')
    print('Added 47 original questions: Part 5 +10, Part 6 +20, Part 7 +17.')
if __name__=='__main__': main()
